package webui

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"trident/internal/codescan"
)

const codeCacheVersion = "p3.0"

// codeCachePath returns the per-snapshot cache file. A snapshot-only console
// has no workspace, so it keeps the previous in-memory behavior.
func (c *Console) codeCachePath(snapshotHash string) (string, bool) {
	if c.workspace == "" || snapshotHash == "" {
		return "", false
	}
	return filepath.Join(c.workspace, "cache", "code-audit", snapshotHash+"."+codeCacheVersion+".json"), true
}

// loadCodeCache accepts only a report generated by this tool version for the
// same snapshot. A corrupt or stale cache is ignored; the caller re-analyzes.
func (c *Console) loadCodeCache(snapshotHash string) (*codescan.Report, bool) {
	path, ok := c.codeCachePath(snapshotHash)
	if !ok {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil || len(data) == 0 || len(data) > 128<<20 {
		return nil, false
	}
	var report codescan.Report
	if err := json.Unmarshal(data, &report); err != nil {
		return nil, false
	}
	if report.SchemaVersion != codescan.SchemaVersion ||
		report.ToolVersion != codescan.ToolVersion ||
		report.SnapshotHash != snapshotHash ||
		!strings.HasPrefix(report.RuleSetVersion, codescan.RuleSetVersion) {
		return nil, false
	}
	return &report, true
}

func (c *Console) saveCodeCache(report codescan.Report) {
	path, ok := c.codeCachePath(report.SnapshotHash)
	if !ok {
		return
	}
	data, err := json.Marshal(report)
	if err != nil {
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache encode failed: %v\n", err)
		return
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache directory failed: %v\n", err)
		return
	}
	file, err := os.CreateTemp(filepath.Dir(path), ".code-audit-*.tmp")
	if err != nil {
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache temp failed: %v\n", err)
		return
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		_ = file.Close()
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache write failed: %v\n", err)
		return
	}
	if err := file.Close(); err != nil {
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache close failed: %v\n", err)
		return
	}
	if err := os.Rename(name, path); err != nil {
		fmt.Fprintf(os.Stderr, "TRIDENT code audit cache rename failed: %v\n", err)
	}
}
